            unlock.input.checked = cameraUnlocked;

            usbToggle.input.checked = usbAdvanced;
            usbSimple.hidden = usbAdvanced;
            usbAdvancedView.hidden = !usbAdvanced;
            usbRadios.forEach((node, i) => { node.input.checked = state.usbPreset === i + 1; });
