/* ---- js/app/tab-profiles.js ---- */
/*  OpenFIRE Web App - "Calibration Profiles" tab (Qt: profilesTab).

    One row per profile: rename, active profile (selected immediately on the board),
    calibration values, IR sensitivity, run mode, layout, aspect ratio and colour.
    "Calibrate Profile N" opens the fullscreen calibration window.
*/
(function (root) {
    'use strict';

    const OF = root.OF = root.OF || {};

    const TAB_HELP = '<html><head/><body><p>This tab shows information and settings to tweak about your current calibration profiles.</p><p>The table above represents the amount of profiles the current board can store, including currently selected profile, names shown for each profile when using a compatible <span style=" font-style:italic;">I2C Display,</span> and colors used for lighting devices when switching to them from <span style=" font-style:italic;">Pause Mode.</span></p><p>Hover over an option to view detailed info about it here.</p></body></html>';
    const SERIAL_LINK = "<a href='https://github.com/TeamOpenFIRE/OpenFIRE-Firmware/wiki/MAMEHOOKER-Documentation#m---mode-commands'><span style=' text-decoration: underline; color:#8ab4f8;'>Serial command</span></a> ";

    const HELP = {
        rename: ['Rename Profile %1',
            '<p>Click to rename this Calibration Profile.</p>' +
            '<p>Aside from differentiating between different profiles for different displays, ' +
            'Cali Profile names are displayed in Pause Mode when using a compatible <i>I2C Display.</i></p>'],
        irSensitivity: ['Camera Sensitivity for Profile %1',
            '<p>This setting determines the sensitivity of the IR Camera for this Calibration Profile.</p>' +
            '<p>If the camera seems to have trouble picking up IR emitters (and is causing coarse cursor movement), ' +
            'adjusting this setting higher might fix issues with tracking.<br>' +
            'Conversely, setting sensitivity too high may cause indirect IR sources ' +
            '(such as sunlight or IR bouncing off of reflective surfaces) ' +
            'to be picked up instead, causing the cursor to jitter or erratically jump across the screen.</p>'],
        runMode: ['Camera Position Averaging Mode for Profile %1',
            '<p>This setting determines the cursor Averaging Mode for this Calibration Profile.</p>' +
            '<p>The movement of the aiming cursor can be smoothed out by averaging a select number of frames, ' +
            'at the cost of a small increase in latency; conversely, disabling this position averaging can ' +
            'reduce latency, at the cost of some added jitter in mouse movement.</p>' +
            '<p>The default is <b>1-Frame Avg</b>, which should be the preferred balance for most people.</p>'],
        layoutType: ['IR Emitter Layout for Profile %1',
            '<p>This setting determines the IR Layout to be used with this Calibration Profile.</p>' +
            '<p>Each Cali Profile can be set to use either the <i>Square Layout,</i> ' +
            'which uses two pairs of emitters on the top and bottom, and <i>Diamond Layout,</i> ' +
            'which uses one emitter at the center of each side of the display.</p>' +
            '<p><i>Square Layout</i> generally has much higher accuracy at any angle and allows for ' +
            'playing closer to the screen or using external Fish Eye lenses without viewport distortion, ' +
            'while <i>Diamond Layout</i> is for screen compatibility with certain legacy lightgun systems ' +
            '(allowing OpenFIRE guns to play with such other lightgun systems on the same display).</p>' +
            '<p>If unsure, use <b>Square Layout</b> ' +
            '(unless you also use a different brand of lightgun that needs a diamond IR layout to function).</p>'],
        aspectRatio: ['Aspect Ratio Correction for Profile %1',
            '<p>This setting determines the type of Aspect Ratio Correction used for this Profile when <i>4:3 Mode</i> is set.</p>' +
            '<p>When ' + SERIAL_LINK +
            '<tt>M3x1</tt> is received, the firmware stretches the effective range for fullscreen applications in Windows ' +
            'that runs in resolutions <b>narrower</b> than the full display width/height; ' +
            'this setting determines the stretch factor that will be used for these 4:3 applications.</p>' +
            '<p>Do note that this restriction exclusively applies to the <b>Windows Operating System ONLY ' +
            "for legacy applications that DON'T support the monitor's full resolution;</b> <i>Linux-based systems</i> and games run via <i>Wine/Proton</i> " +
            '<b>do not need this workaround,</b> except for certain applications like <i>CXBX-Reloaded</i> that don\'t scale down the effective range correctly for 4:3 content.</p>' +
            '<p>If unsure, set to <b>the aspect ratio of your display.</b> Setting to <i>4:3</i> effectively disables range stretching when toggled.</p>'],
        color: ['Profile Menu Color for Cali Profile %1',
            '<p>Open a window to select the color used to represent this profile in <i>Pause Mode.</i></p>' +
            '<p>Each profile can be assigned a color used to identify them when switching profiles on the lightgun itself, ' +
            'which is emitted by a 4-pin RGB LED and/or an active NeoPixel strand.</p>'],
        calibrate: ['Open Calibration Window for Cali Profile %1', 'Click to start the calibration process for this profile.'],
    };

    const VALUE_COLUMNS = [
        ['topOffset', 'Top'], ['bottomOffset', 'Bottom'], ['leftOffset', 'Left'],
        ['rightOffset', 'Right'], ['TLled', 'TLled'], ['TRled', 'TRled'],
    ];
    const OPTION_COLUMNS = [
        ['irSensitivity', 'Sensitivity', 'irSensitivity'], ['runMode', 'Run Mode', 'runModes'],
        ['layoutType', 'Layout', 'layouts'], ['aspectRatio', 'Display Ratio', 'aspectRatios'],
    ];

    /** Qt QString::number: offsets are integers, TLled/TRled floats ("%g", 6 significant digits). */
    function formatNumber(value, isFloat) {
        return isFloat ? OF.UI.formatG(value) : String(Math.trunc(Number(value)));
    }

    function build(app) {
        const { el, t, icon, select } = OF.UI;
        const state = app.state;
        const desc = new OF.UI.DescriptionBox(t(TAB_HELP));
        const help = (key, n) => [t(HELP[key][0], n), t(HELP[key][1], n)];

        const table = el('table', { class: 'profiles-table' });
        const tableScroll = el('div', { class: 'table-scroll' }, table);
        const buttons = el('div', { class: 'cali-buttons' });

        // The whole table is shown: it shrinks instead of being scrolled sideways
        // (on narrow screens it is scrolled as usual).
        const wide = root.matchMedia ? root.matchMedia('(min-width: 761px)') : null;
        const fit = () => OF.UI.fitToWidth(tableScroll, table, 0.6, !wide || wide.matches);
        OF.UI.fitOnResize(tableScroll, fit);
        if (wide && wide.addEventListener) wide.addEventListener('change', fit);
        const rootNode = el('div', { class: 'tab-body' },
            el('div', { class: 'tab-scroll' },
                el('div', { class: 'tab-content' },
                    el('fieldset', { class: 'group' }, el('legend', { text: t('Calibration Profiles') }),
                        tableScroll, buttons))),
            desc.root);

        let rows = [];
        let builtCount = -1;

        function populate() {
            table.textContent = '';
            buttons.textContent = '';
            rows = [];
            builtCount = state.profileCount;

            table.append(el('thead', null, el('tr', null,
                el('th', { attrs: { colspan: 2 } }),
                ...VALUE_COLUMNS.map(([, title]) => el('th', { text: t(title) })),
                ...OPTION_COLUMNS.map(([, title]) => el('th', { text: t(title) })),
                el('th', { text: t('Color') }))));

            const body = el('tbody');
            for (let i = 0; i < builtCount; ++i) {
                const n = i + 1;
                const rename = el('button', { class: 'icon-button', title: t(HELP.rename[0], n), attrs: { 'aria-label': t(HELP.rename[0], n) },
                    on: { click: () => renameProfile(i) } }, icon('edit'));
                desc.track(rename, ...help('rename', n));

                const radioInput = el('input', { type: 'radio', name: 'of-profile' });
                const radioText = el('span', { class: 'mono' });
                const radio = el('label', { class: 'check radio profile-radio' }, radioInput, radioText);
                radio.input = radioInput;
                radioInput.addEventListener('change', () => { if (radioInput.checked) selectProfile(i); });

                const values = VALUE_COLUMNS.map(() => el('td', { class: 'mono value' }));
                const options = OPTION_COLUMNS.map(([key, , list]) => {
                    const box = select(OF.Maps[list].map((label, value) => ({ value, label: t(label) })), 0, (value) => {
                        state.setProfileField(i, key, Number(value));
                        app.refresh();
                    }, { attrs: { 'aria-label': t(HELP[key][0], n) } });
                    desc.track(box, ...help(key, n));
                    return box;
                });

                const swatch = el('span', { class: 'color-swatch' });
                const color = el('button', { class: 'color-button only', title: t(HELP.color[0], n), attrs: { 'aria-label': t(HELP.color[0], n) },
                    on: { click: () => chooseColor(i) } }, swatch);
                desc.track(color, ...help('color', n));

                body.append(el('tr', null,
                    el('td', null, rename), el('td', null, radio),
                    ...values,
                    ...options.map((box) => el('td', null, box)),
                    el('td', null, color)));

                const calibrate = el('button', { text: t('Calibrate Profile %1', n), on: { click: () => app.calibrate(i) } });
                desc.track(calibrate, ...help('calibrate', n));
                buttons.append(calibrate);

                rows.push({ radio, radioText, values, options, swatch, calibrate });
            }
            table.append(body);
        }

        async function renameProfile(i) {
            const session = app.session;
            const name = await OF.UI.prompt(t('Input Name'), t('Set name for Calibration Profile %1', i + 1),
                { value: state.cur.profiles[i].name, maxLength: OF.AppState.NAME_MAX, latin1: true, scope: 'session' });
            if (session !== app.session || !state.loaded || app.busy) return;
            if (name) state.renameProfile(i, name);
            app.refresh();
        }

        async function chooseColor(i) {
            const session = app.session;
            const color = await OF.UI.pickColor(t(HELP.color[0], i + 1), state.cur.profiles[i].color, { scope: 'session' });
            if (session !== app.session || !state.loaded || app.busy) return;
            if (color !== null) {
                state.setProfileField(i, 'color', color);
                app.refresh();
            }
        }

        function selectProfile(i) {
            if (i !== state.cur.selectedProfile) app.selectProfile(i);
        }

        function update() {
            if (!state.loaded) return;
            if (builtCount !== state.profileCount) populate();
            fit();
            const locked = app.commitNeedsRetry;
            rows.forEach((row, i) => {
                const profile = state.cur.profiles[i];
                row.radioText.textContent = `${i + 1}. ${profile.name}`;
                row.radio.input.checked = i === state.cur.selectedProfile;
                row.radio.input.disabled = locked;
                VALUE_COLUMNS.forEach(([key], column) => { row.values[column].textContent = formatNumber(profile[key], key === 'TLled' || key === 'TRled'); });
                OPTION_COLUMNS.forEach(([key], column) => { row.options[column].value = String(profile[key]); });
                row.swatch.style.background = OF.UI.toHex(profile.color);
                row.calibrate.disabled = locked;
            });
        }

        return { root: rootNode, update, onShow() { desc.reset(); }, reload() { builtCount = -1; update(); } };
    }

    OF.Tabs = OF.Tabs || {};
    OF.Tabs.profiles = { id: 'profiles', label: 'Calibration Profiles', icon: 'profiles', build, formatNumber };
})(typeof globalThis !== 'undefined' ? globalThis : this);
;

/* ---- js/app/tab-tests.js ---- */
/*  OpenFIRE Web App - "Gun Tests" tab (Qt: testsTab).

    Live button/temperature/analog stick readings sent by the docked board, feedback tests,
    the IR camera tester and the board actions (bootloader, clear save memory).
    It describes the board as it was loaded or last saved (state.testPins).
*/
(function (root) {
    'use strict';

    const OF = root.OF = root.OF || {};

    function build(app) {
        const { el, t } = OF.UI;
        const state = app.state;
        const S = state.S;
        const E = state.E;
        const T = state.T;
        const C = S.serialCmdTypes_e;
        const names = OF.Maps.functionNames(S);

        // ----- Inputs test ---------------------------------------------------------------
        const buttonLabels = [];
        const buttonGrid = el('div', { class: 'test-buttons' });
        for (let i = 0; i < OF.Maps.BUTTON_COUNT; ++i) {
            const label = el('div', { class: 'test-button' });
            buttonLabels.push(label);
            buttonGrid.append(label);
        }
        const temperature = el('div', { class: 'temperature' });
        const buttonsGroup = el('fieldset', { class: 'group' }, el('legend', { text: t('Buttons') }), buttonGrid, temperature);

        const positionLabel = el('div', { class: 'analog-label mono' });
        const dot = el('svg:circle', { attrs: { cx: 128, cy: 128, r: 8 } });
        const analogView = el('svg:svg', { class: 'analog-view', attrs: { viewBox: '0 0 256 256', role: 'img', 'aria-label': t('Analog Stick') } },
            el('svg:line', { class: 'axis', attrs: { x1: 128, y1: 0, x2: 128, y2: 256 } }),
            el('svg:line', { class: 'axis', attrs: { x1: 0, y1: 128, x2: 256, y2: 128 } }),
            dot);
        const analogGroup = el('fieldset', { class: 'group analog-group' }, el('legend', { text: t('Analog Stick') }), positionLabel, analogView);

        const inputsTest = el('fieldset', { class: 'group' }, el('legend', { text: t('Inputs Test') }),
            el('div', { class: 'inputs-test' }, buttonsGroup, analogGroup));

        // ----- Feedback tests -----------------------------------------------------------------
        const testButton = (label, command, message) => el('button', { text: t(label), on: { click: async () => {
            if (await app.sendCommand(command)) app.status.show(t(message), 2500);
        } } });
        const rumbleTest = testButton('Test Rumble Motor', C.sTestRumble, 'Sent a rumble test pulse.');
        const solenoidTest = testButton('Test Solenoid', C.sTestSolenoid, 'Sent a solenoid test pulse.');
        const redTest = testButton('Test Red LED', C.sTestLEDR, 'Set LED to Red.');
        const greenTest = testButton('Test Green LED', C.sTestLEDG, 'Set LED to Green.');
        const blueTest = testButton('Test Blue LED', C.sTestLEDB, 'Set LED to Blue.');
        const feedbackTests = el('fieldset', { class: 'group' }, el('legend', { text: t('Feedback Tests') }),
            el('div', { class: 'row fill feedback-row' }, rumbleTest, solenoidTest),
            el('div', { class: 'row fill feedback-row' }, redTest, greenTest, blueTest));

        const irTest = el('button', { class: 'wide-button', text: t('Open IR Camera Tester...'), on: { click: () => app.openIRTest() } });

        // ----- Board actions --------------------------------------------------------------------
        const reboot = el('button', { on: { click: () => app.rebootToBootloader() } });
        const clear = el('button', { class: 'danger-text', text: t('Clear Save Memory [!]'), on: { click: () => app.clearSaveMemory() } });
        const boardActions = el('fieldset', { class: 'group' }, el('legend', { text: t('Board Actions') }),
            el('div', { class: 'row fill board-actions' }, reboot, clear));

        const content = el('div', { class: 'tab-content narrow' }, inputsTest, feedbackTests, irTest, el('hr'), boardActions);
        const scroll = el('div', { class: 'tab-scroll' }, content);
        const rootNode = el('div', { class: 'tab-body' }, scroll);

        // Like the board layout: the whole tab is shown, it shrinks instead of being scrolled
        // (on narrow screens the single column is scrolled as usual).
        const wide = root.matchMedia ? root.matchMedia('(min-width: 761px)') : null;
        const fit = () => OF.UI.fitToHeight(scroll, content, 0.6, !wide || wide.matches);
        OF.UI.fitOnResize(scroll, fit);
        if (wide && wide.addEventListener) wide.addEventListener('change', fit);

        const mapped = (fn) => (state.testPins[fn] ?? -1) >= 0;

        /**
         * Name of an input box: the plain name when it has a pin; '(N/C)' when it has none.
         * The two pedals also work without a pin, over the air: when the board is in that mode
         * they say so, and add that nothing answered when no pedal is paired.
         */
        function inputLabel(index) {
            const name = t(names[index + 1]);
            if (mapped(index))
                return { text: name, connected: true };
            if (state.isPedal(index) && state.pedalWirelessMode)
                return state.pedalWireless ?
                    { text: t('%1 (wireless)', name), connected: true } :
                    { text: t('%1 (wireless, disconnected)', name), connected: false };
            return { text: `${name} (N/C)`, connected: false };
        }

        /** Qt LabelsUpdate: on load and after a save. */
        function resetReadings() {
            buttonLabels.forEach((label, i) => {
                label.classList.remove('pressed');
                const { text, connected } = inputLabel(i);
                label.textContent = text;
                label.classList.toggle('not-connected', !connected);
            });
            temperature.className = 'temperature';
            if (mapped(E.tempPin)) {
                temperature.textContent = t('Temperature Read...');
                temperature.classList.remove('not-connected');
            } else {
                temperature.textContent = t('Temperature Sensor (N/C)');
                temperature.classList.add('not-connected');
            }
            const analog = mapped(E.analogX) && mapped(E.analogY);
            positionLabel.textContent = analog ? '' : t('Not Connected');
            dot.setAttribute('cx', 128);
            dot.setAttribute('cy', 128);
        }

        function update() {
            if (!state.loaded) return;
            const recovery = app.commitNeedsRetry;
            const testing = app.irTestActive;
            inputsTest.disabled = recovery || testing;
            feedbackTests.disabled = recovery || testing;
            irTest.disabled = recovery;
            boardActions.disabled = testing;
            analogGroup.disabled = !(mapped(E.analogX) && mapped(E.analogY));
            rumbleTest.disabled = !state.toggle(state.B.rumble);
            solenoidTest.disabled = !state.toggle(state.B.solenoid);
            redTest.disabled = !mapped(E.ledR);
            greenTest.disabled = !mapped(E.ledG);
            blueTest.disabled = !mapped(E.ledB);
            reboot.textContent = t(state.isRP ? 'Reboot to Bootloader' : 'Restart Microcontroller in Firmware Update Mode');
            fit();
        }

        /** Board events for this tab. Returns true when handled. */
        function onEvent(command, payload) {
            switch (command) {
            case C.sBtnPressed:
            case C.sBtnReleased:
                if (payload.length === 1 && payload[0] < buttonLabels.length)
                    buttonLabels[payload[0]].classList.toggle('pressed', command === C.sBtnPressed);
                return true;
            case C.sTemperatureUpd: {
                if (payload.length !== 1) return true;
                const temp = payload[0];
                temperature.classList.remove('not-connected', 'hot', 'warm', 'ok', 'fault');
                if (temp === S.TEMPERATURE_SENSOR_ERROR_VALUE) {
                    temperature.textContent = t('Temperature: FAULT');
                    temperature.classList.add('fault');
                    return true;
                }
                temperature.textContent = t('Temperature: %1°C', temp);
                if (temp > state.orig.settings[T.tempShutdown]) temperature.classList.add('hot');
                else if (temp > state.orig.settings[T.tempWarning]) temperature.classList.add('warm');
                else temperature.classList.add('ok');
                return true;
            }
            case C.sAnalogPosUpd: {
                if (payload.length !== 4) return true;
                const view = new DataView(payload.buffer, payload.byteOffset, 4);
                const x = view.getUint16(0, true);
                const y = view.getUint16(2, true);
                // Qt: uint8_t pos = ~(value / 16)
                dot.setAttribute('cx', (~Math.floor(x / 16)) & 0xFF);
                dot.setAttribute('cy', (~Math.floor(y / 16)) & 0xFF);
                positionLabel.textContent = `${x} , ${y}`;
                return true;
            }
            default:
                return false;
            }
        }

        return { root: rootNode, update, onEvent, resetReadings, onLoad: resetReadings };
    }

    OF.Tabs = OF.Tabs || {};
    OF.Tabs.tests = { id: 'tests', label: 'Gun Tests', icon: 'tests', build };
})(typeof globalThis !== 'undefined' ? globalThis : this);
;

/* ---- js/app/version.js ---- */
/*  OpenFIRE Web App - the version check of a published App.

    Every version of the App stays published, each in its own folder (v/<version>/ of the
    site), and the home page of the site is the one that chooses: it reads the version of
    the firmware and opens the App published for it (webapp/launcher/). An App, once open,
    never goes looking for another one - it is the App of its version and it stays that.

    All it does is this: if the lightgun runs a firmware of another version, say so and let
    the user decide whether to carry on or to go back to the home page, which opens the
    right one. That is the whole of this file.

      afterDock(app, board)  once docked: the question, when the versions differ.
      resume(app)            arrived from the home page: take the port back, say why.

    The App embedded in the lightgun does not include this file at all
    (scripts/webapp_build.py leaves it out of the device build): the gun serves the App of
    its own firmware, so there is nothing to check, and every call to OF.Version elsewhere
    is guarded.
*/
(function (root) {
    'use strict';

    const OF = root.OF = root.OF || {};

    const JUMP_KEY = 'of_version_jump';    // left by the home page for the App it opens

    const store = {
        get(key) { try { return root.sessionStorage.getItem(key); } catch (e) { return null; } },
        drop(key) { try { root.sessionStorage.removeItem(key); } catch (e) { /* private mode */ } },
    };

    /** The folder of this page, without the file name. */
    const pageFolder = (path) => String(path || '').replace(/[^/]*$/, '');

    /** True when this page is one of the published versions, v/<version>/ of a site: then
        there is a home page to go back to. A copy opened from anywhere else (a folder on
        the disk, the desktop app) has nowhere to send anybody. */
    const isPublished = (path) => /\/v\/[^/]+\/$/.test(pageFolder(path));

    /** The home page of the site this version belongs to. */
    const siteHome = (path) => {
        const folder = pageFolder(path);
        const match = folder.match(/^(.*\/)v\/[^/]+\/$/);
        return match ? match[1] : folder;
    };

    const here = () => (root.location && root.location.pathname) || '';
    const isSite = () => !!(OF.BUILD && OF.BUILD.target === 'site');
    const myVersion = () => String((OF.BUILD && OF.BUILD.version) || '');
    const myLabel = () => String((OF.BUILD && (OF.BUILD.versionLabel || OF.BUILD.version)) || '');
    const langSuffix = () => {
        const lang = OF.i18n ? OF.i18n.currentLang : '';
        return lang ? '?lang=' + encodeURIComponent(lang) : '';
    };

    /** The version of a firmware as it names a folder: "6.2" out of "6.2-<git hash>". */
    const shortOf = (board) => String((board && board.version) || '').split('-')[0].trim();

    OF.Version = {
        isPublished, siteHome,

        /** Once docked: when the firmware is of another version, ask what to do. Returns
            true when the question was asked. */
        async afterDock(app, board) {
            if (!isSite()) return false;
            const mine = myVersion();
            const short = shortOf(board);
            if (!mine || !short || short === mine) return false;
            if (this.asked === short) return false;   // once per version, not at every dock
            this.asked = short;

            const t = OF.UI.t;
            const theirs = String((board && board.versionFull) || '').trim() || short;
            const text = t('This is the App of version %1, while the lightgun runs firmware %2.', myLabel(), theirs);

            // Nowhere to go back to: this copy is not part of a published site.
            if (!isPublished(here())) {
                await OF.UI.alert(t('Versions do not match'), OF.UI.escape(text +
                    '\n\n' + t('They can still work together, but something may not match.')), 'warning');
                return true;
            }

            const carryOn = await OF.UI.dialog({
                title: t('Versions do not match'),
                icon: 'warning',
                text,
                info: t('They can still work together, but something may not match.\n\nCarry on anyway, or go back to the home page, which opens the App published for this firmware?'),
                buttons: [
                    { label: t('Carry on'), value: true },
                    { label: t('Go back'), value: false, primary: true },
                ],
                cancelValue: false,          // closing the window is going back
            });
            if (!carryOn) await this.goHome(app);
            return true;
        },

        /** Undocks the lightgun for good and goes back to the home page of the site. */
        async goHome(app) {
            try {
                if (app && app.connection && app.connection.isDocked) await app.disconnect();
            } catch (error) { /* going away anyway */ }
            root.location.href = siteHome(here()) + langSuffix();
        },

        /** Opened by the home page: take the port back without asking - the browser gives
            a page the ports already allowed on this site - and say why we are here, once
            the messages of the docking are over. */
        async resume(app) {
            let jump = null;
            try {
                const raw = store.get(JUMP_KEY);
                store.drop(JUMP_KEY);
                jump = raw ? JSON.parse(raw) : null;
            } catch (error) {
                return;
            }
            if (!jump) return;

            if (jump.latest && String(jump.latest) !== myVersion()) {
                app.versionNotice = OF.UI.t('App %1, published for the firmware of this lightgun. A newer firmware is available: %2.',
                                            myLabel(), String(jump.latestLabel || jump.latest));
                app.status.show(app.versionNotice, 12000);
            }

            if (!OF.WebSerialTransport.isSupported()) return;
            let ports = [];
            try {
                ports = await OF.WebSerialTransport.getKnownPorts();
            } catch (error) {
                return;
            }
            if (!ports.length) return;
            const wanted = jump.port || {};
            const port = ports.find((item) => {
                const info = OF.WebSerialTransport.describePort(item);
                return info.productId === wanted.productId && info.vendorId === wanted.vendorId;
            }) || (ports.length === 1 ? ports[0] : null);
            if (port) await app.connectPort(port);
        },
    };
})(typeof globalThis !== 'undefined' ? globalThis : this);
;

/* ---- js/app/main.js ---- */
/*  OpenFIRE Web App - main window (Qt: appmainwindow.cpp).

    Menu bar, title, the five tabs, status bar with Save and Disconnect; connection and
    board events. The site connects with the Connect button (Web Serial); the lightgun page
    (OF.BUILD.target 'device') connects by itself over WebSocket, has no board previews and
    is never undocked by hand.
*/
(function (root) {
    'use strict';

    const OF = root.OF = root.OF || {};
    const doc = root.document;

    const APP_NAME = 'OpenFIRE Esp32';   // shown where the App names itself (title, welcome, About)
    const THEME_KEY = 'of_theme';
    const TAB_ORDER = ['pins', 'buttons', 'settings', 'profiles', 'tests'];
    const THEME_ICONS = { system: 'themeSystem', light: 'themeLight', dark: 'themeDark' };
    const THEME_LABELS = { system: 'System Theme', light: 'Light Theme', dark: 'Dark Theme' };
    const DOCS_URL = 'https://github.com/TeamOpenFIRE/OpenFIRE-Firmware/blob/OpenFIRE-dev/OpenFIREmain/README.md';
    const WIKI_URL = 'https://github.com/TeamOpenFIRE/OpenFIRE-Firmware/wiki';

    const storage = {
        get(key) { try { return root.localStorage.getItem(key); } catch (e) { return null; } },
        set(key, value) { try { root.localStorage.setItem(key, value); } catch (e) { /* private mode */ } },
    };

    /** Menu texts of the Qt App carry '&' accelerators. */
    const menuText = (key) => OF.UI.t(key).replace(/&(?=[^&\s])/, '');

    // Whether this App is the one of the lightgun that is connected is checked in
    // js/app/version.js (OF.Version), which the App embedded in the lightgun does not
    // include at all: every call here is guarded accordingly.

    class App {
        constructor() {
            this.S = OF.Boards.shared;
            this.C = this.S.serialCmdTypes_e;
            this.state = new OF.AppState(this.S);
            this.connection = new OF.Connection({ onDockFailure: (result, protocol, kind) => this.onDockFailure(result, protocol, kind) });
            this.protocol = this.connection.protocol;
            this.busy = false;            // Qt serialActive: a transaction is running
            this.irTestActive = false;
            this.window = null;           // fullscreen window
            this.caliProfile = -1;
            this.expectClose = false;     // the page closes the link itself (bootloader, clear)
            this.session = 0;             // increases at every dock and undock: stale awaits check it
            this.lostEdits = null;        // unsaved edits of a session lost by accident
            this.portArch = new Map();    // Web Serial port -> architecture of its last dock
            this.irTestStarting = false;
            this.showUnsafe = false;      // like the Qt App, not remembered
            this.theme = storage.get(THEME_KEY) || 'system';
            this.currentTab = 'pins';
            this.activePort = null;
            this.tabs = {};
            this.titleName = '';
            this.versionNotice = '';      // why this page opened, said again once docked
        }

        get isDevice() { return OF.Boards.isDevice; }
        get commitNeedsRetry() { return this.protocol.commitNeedsRetry(); }
        get connected() { return this.state.loaded && this.connection.isDocked; }

        start() {
            this.applyTheme();
            this.render();
            OF.i18n.on('change', () => this.render());

            this.connection.on('state', (state, detail) => this.onConnectionState(state, detail || {}));
            this.connection.on('docked', ({ board, config }) => this.onDocked(board, config));
            this.connection.on('event', (command, payload) => this.onEvent(command, payload));
            this.connection.on('progress', (progress) => this.onProgress(progress));

            if (root.matchMedia) {
                root.matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change', () => this.applyTheme());
            }

            this.status.show(OF.UI.t('Welcome to the OpenFIRE app!'), 3000);
            this.connection.start();
            if (OF.Version) OF.Version.resume(this);
            // Unsaved edits: the browser asks before leaving the page.
            root.addEventListener('beforeunload', (event) => {
                if (this.state.isDirty() || this.commitNeedsRetry && this.state.loaded) {
                    event.preventDefault();
                    event.returnValue = '';
                }
            });
            // The gun goes back to Run mode when the page really goes away.
            root.addEventListener('pagehide', () => { if (this.connection.isDocked) this.protocol.disconnect(); });
            // Back from the browser cache the link is closed: start again.
            root.addEventListener('pageshow', (event) => { if (event.persisted) root.location.reload(); });
            // Qt App shortcuts of the Help menu.
            doc.addEventListener('keydown', (event) => {
                if (!event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
                if (this.window) return; // the fullscreen windows have no menu
                const url = event.code === 'KeyD' ? DOCS_URL : event.code === 'KeyS' ? WIKI_URL : null;
                if (!url) return;
                event.preventDefault();
                root.open(url, '_blank', 'noopener');
            });
        }

        // ----- Theme ----------------------------------------------------------------------

        applyTheme() {
            const html = doc.documentElement;
            if (this.theme === 'light' || this.theme === 'dark') html.dataset.theme = this.theme;
            else delete html.dataset.theme;
        }

        setTheme(theme) {
            this.theme = theme;
            storage.set(THEME_KEY, theme);
            this.applyTheme();
            this.updateThemeButton();
        }

        // ----- Page structure -----------------------------------------------------------------

        render() {
            const { el, t, icon } = OF.UI;
            const app = doc.getElementById('app');
            const settingsView = this.tabs.settings && this.tabs.settings.saveViewState();
            app.textContent = '';
            OF.UI.closeMenus();

            // Menu bar
            const menubar = el('nav', { class: 'menubar', attrs: { 'aria-label': 'Menu' } },
                el('span', { class: 'menubar-logo', html: OF.LOGO_SVG, attrs: { 'aria-hidden': 'true' } }),
                this.isDevice ? null : el('button', { class: 'menu-button', text: t('Board Previews'), on: { click: () => OF.Windows.openPreviewer(this.state.board && this.state.board.type) } }),
                el('button', { class: 'menu-button', text: t('Emitter Alignment'), on: { click: () => this.openAlignment() } }),
                OF.UI.menu(t('View'), () => [
                    { label: t('Show Unsafe Settings'), checked: this.showUnsafe, action: () => this.setUnsafe(!this.showUnsafe) },
                    { label: t('Debug Window'), action: () => this.openDebugWindow(), hidden: !this.debugEnabled },
                ]),
                OF.UI.menu(menuText('&Help'), () => [
                    { label: t('View Compatible Boards'), action: () => OF.Windows.openPreviewer(this.state.board && this.state.board.type), hidden: this.isDevice },
                    { label: menuText('Open &IR Emitter Alignment Assistant'), action: () => this.openAlignment() },
                    { separator: true },
                    { label: menuText('&OpenFIRE Documentation on the Repo...'), href: DOCS_URL, shortcut: 'Alt+D' },
                    { label: menuText('OpenFIRE &Serial Usage Docs on the Wiki...'), href: WIKI_URL, shortcut: 'Alt+S' },
                    { separator: true },
                    { label: t('About'), action: () => OF.Windows.openAbout() },
                ]),
                el('span', { class: 'spacer' }),
                this.themeSelector(), this.languageSelector());

            this.titleNode = el('h1', { class: 'board-title' });
            this.versionNode = el('div', { class: 'fw-version' });
            const header = el('header', { class: 'app-header' }, menubar,
                el('div', { class: 'title-block' }, this.titleNode, this.versionNode));

            // Welcome (not connected)
            this.welcome = this.buildWelcome();

            // Tabs
            this.panels = {};
            const main = el('main', { class: 'content' }, this.welcome);
            const tabbar = el('nav', { class: 'tabbar', attrs: { role: 'tablist' } });
            this.tabButtons = {};
            for (const id of TAB_ORDER) {
                const module = OF.Tabs[id];
                const tab = module.build(this);
                this.tabs[id] = tab;
                const panel = el('section', { class: 'tab-panel', id: `tab-${id}`, attrs: { role: 'tabpanel' } }, tab.root);
                this.panels[id] = panel;
                main.append(panel);
                const button = el('button', { class: 'tab-button', attrs: { role: 'tab', 'aria-controls': `tab-${id}` },
                    on: { click: () => this.selectTab(id) } }, icon(module.icon), el('span', { class: 'tab-label', text: t(module.label) }));
                this.tabButtons[id] = button;
                tabbar.append(button);
            }
            this.main = main;
            this.tabbar = tabbar;

            // Status bar
            const statusText = el('span', { class: 'status-text', attrs: { role: 'status' } });
            const progress = el('progress', { class: 'status-progress', hidden: true });
            this.saveButton = el('button', { class: 'primary save-button', on: { click: () => this.save() } },
                icon('save'), el('span', { class: 'save-label' }));
            const previousStatus = this.status;
            this.status = new OF.UI.StatusBar(statusText, progress);
            this.status.adopt(previousStatus);
            // The docked lightgun does not shoot: this sends it back to Run mode and frees
            // its port for another App, without closing the page (never on the lightgun page).
            this.disconnectButton = this.isDevice ? null :
                el('button', { class: 'disconnect-button', hidden: true, text: t('Disconnect'), on: { click: () => this.disconnect() } });
            // State of the link with the lightgun, in both builds: plug and socket joined
            // when a board is docked, pulled apart when not (they blink while connecting).
            // Last in the bar, so the corner keeps it in the same place with or without the button.
            this.linkIcon = icon('unplugged');
            this.linkState = el('span', { class: 'link-state' }, this.linkIcon);
            const footer = el('footer', { class: 'app-footer' }, tabbar,
                el('div', { class: 'statusbar' },
                    el('div', { class: 'status-side' }, statusText, progress),
                    this.saveButton,
                    el('div', { class: 'status-side' }, this.disconnectButton, this.linkState)));

            app.append(header, main, footer);

            if (this.state.loaded) {
                if (settingsView) this.tabs.settings.restoreViewState(settingsView);
                this.tabs.tests.resetReadings();
                this.updateHeader();
            }
            this.selectTab(this.currentTab, true);
            this.refresh();
        }

        /** Theme, next to the language: the icon shows the one in use, the menu has the three choices. */
        themeSelector() {
            const { t, icon, menu } = OF.UI;
            this.themeIcon = icon(THEME_ICONS[this.theme] || THEME_ICONS.system);
            const wrap = menu(this.themeIcon, () => [
                { label: t('System Theme'), checked: this.theme === 'system', action: () => this.setTheme('system') },
                { label: t('Light Theme'), checked: this.theme === 'light', action: () => this.setTheme('light') },
                { label: t('Dark Theme'), checked: this.theme === 'dark', action: () => this.setTheme('dark') },
            ], { class: 'menu-button theme-button' });
            wrap.classList.add('theme-menu');
            this.themeButton = wrap.querySelector('.menu-button');
            this.updateThemeButton();
            return wrap;
        }

        /** Icon and tooltip of the theme button: they name the theme in use. */
        updateThemeButton() {
            if (!this.themeButton) return;
            const label = OF.UI.t(THEME_LABELS[this.theme] || THEME_LABELS.system);
            const next = OF.UI.icon(THEME_ICONS[this.theme] || THEME_ICONS.system);
            this.themeIcon.replaceWith(next);
            this.themeIcon = next;
            this.themeButton.title = label;
            this.themeButton.setAttribute('aria-label', label);
        }

        languageSelector() {
            const { el } = OF.UI;
            const select = el('select', { class: 'lang-selector', attrs: { 'aria-label': 'Language' } });
            for (const code of OF.i18n.languages())
                select.append(el('option', { value: code, text: OF.i18n.languageName(code) }));
            select.value = OF.i18n.currentLang;
            select.addEventListener('change', () => OF.i18n.setLanguage(select.value));
            return select;
        }

        buildWelcome() {
            const { el, t, icon } = OF.UI;
            this.welcomeText = el('p', { class: 'welcome-text' });
            this.welcomeDetail = el('p', { class: 'welcome-detail', hidden: true });
            const logo = el('div', { class: 'welcome-logo', html: OF.LOGO_SVG });
            const children = [logo, el('div', { class: 'wordmark big', text: APP_NAME }), this.welcomeText, this.welcomeDetail];
            if (this.isDevice) {
                this.spinner = el('div', { class: 'spinner', attrs: { 'aria-hidden': 'true' } });
                this.reconnectButton = el('button', { class: 'primary big-button', hidden: true, on: { click: () => this.connection.reconnect() } },
                    icon('wifi'), el('span', { text: t('Reconnect') }));
                children.push(this.spinner, this.reconnectButton);
            } else if (OF.WebSerialTransport.isSupported()) {
                this.connectButton = el('button', { class: 'primary big-button', on: { click: () => this.addDevice() } },
                    icon('usb'), el('span', { text: t('Connect') }));
                children.push(this.connectButton);
            }
            return el('section', { class: 'welcome' }, ...children);
        }

        updateWelcome() {
            const t = OF.UI.t;
            let text;
            if (this.isDevice) {
                const stopped = this.connection.autoStopped;
                text = stopped ? t('The lightgun was taken over by another page. Close the other page, then press Reconnect.') :
                    this.connection.state === 'error' ? t('Waiting for the lightgun... another App may be using it.') : t('Connecting to the lightgun...');
                this.spinner.hidden = stopped;
                this.reconnectButton.hidden = !stopped;
            } else if (!OF.WebSerialTransport.isSupported()) {
                text = t('This browser does not support Web Serial: use Chrome, Edge or Opera on a computer.');
            } else if (this.connection.state === 'connecting') {
                text = t('Connecting...');
            } else {
                text = t('Connect the lightgun with its USB cable, then select it.');
            }
            this.welcomeText.textContent = text;
            // Why the last attempt failed: useful where there is no console (phone).
            const detail = this.connection.state === 'error' ? this.lastConnectionError : null;
            this.welcomeDetail.textContent = detail ? this.connectionErrorText(detail) : '';
            this.welcomeDetail.hidden = !detail;
            if (this.connectButton) this.connectButton.disabled = this.connection.state === 'connecting';
        }

        selectTab(id, silent) {
            this.currentTab = id;
            for (const tabId of TAB_ORDER) {
                const active = tabId === id;
                this.panels[tabId].hidden = !active;
                this.tabButtons[tabId].classList.toggle('active', active);
                this.tabButtons[tabId].setAttribute('aria-selected', String(active));
            }
            const tab = this.tabs[id];
            if (tab && tab.onShow && !silent) tab.onShow();
        }

        setUnsafe(on) {
            this.showUnsafe = on;
            this.refresh();
        }

        /** Qt DiffUpdate + enable/disable rules, applied to every tab. */
        refresh() {
            const t = OF.UI.t;
            const loaded = this.state.loaded;
            this.welcome.hidden = loaded;
            this.updateWelcome();
            for (const id of TAB_ORDER) {
                const panel = this.panels[id];
                const lockedByTest = this.irTestActive && id !== 'buttons' && id !== 'tests';
                panel.classList.toggle('not-loaded', !loaded);
                panel.inert = !loaded || this.busy || lockedByTest;
                panel.classList.toggle('locked', !!lockedByTest);
                if (!loaded) panel.hidden = true;
                else panel.hidden = id !== this.currentTab;
                this.tabButtons[id].disabled = !loaded || this.busy;
                if (loaded) this.tabs[id].update();
            }

            const label = this.saveButton.querySelector('.save-label');
            let text;
            let enabled = false;
            if (!loaded) text = t('[Currently Not Connected]');
            else if (this.irTestActive) text = t('[Disabled while in Test Mode]');
            else if (this.state.isDirty() || this.commitNeedsRetry) { text = t('Save and Send Settings'); enabled = !this.busy; }
            else text = t('[Nothing To Save]');
            label.textContent = text;
            this.saveButton.disabled = !enabled;
            this.saveButton.classList.toggle('has-changes', enabled);

            if (this.disconnectButton) {
                this.disconnectButton.hidden = !loaded;
                this.disconnectButton.disabled = this.busy || this.irTestActive;
            }
            this.updateLinkState();
            if (!loaded) {
                this.titleNode.textContent = APP_NAME;
                this.versionNode.textContent = '';
            }
        }

        /** Plug of the status bar: docked, connecting (blinking) or not connected. */
        updateLinkState() {
            if (!this.linkState) return;
            const t = OF.UI.t;
            const docked = this.state.loaded;
            const connecting = !docked && this.connection.state === 'connecting';
            const next = OF.UI.icon(docked ? 'plugged' : 'unplugged');
            this.linkIcon.replaceWith(next);
            this.linkIcon = next;
            this.linkState.classList.toggle('on', docked);
            this.linkState.classList.toggle('connecting', connecting);
            this.linkState.title = docked ? t('Connected') : connecting ? t('Connecting...') : t('Not connected');
        }

        updateHeader() {
            const board = this.state.board;
            this.titleNode.textContent = this.state.prettyName(this.titleName, OF.UI.t('Unnamed Device'));
            const version = board.version || '';
            const dash = version.indexOf('-');
            this.versionNode.textContent = '';
            if (dash > -1) {
                const org = this.state.isRP ? 'TeamOpenFIRE' : 'alessandro-satanassi';
                const hash = version.slice(dash + 1);
                this.versionNode.append('FW ', OF.UI.el('tt', null, `v${version.slice(0, dash + 1)}`,
                    OF.UI.el('a', { href: `https://github.com/${org}/OpenFIRE-Firmware/commit/${hash}`, target: '_blank', rel: 'noopener', text: hash })));
            } else if (version) {
                this.versionNode.append('FW ', OF.UI.el('tt', { text: `v${version}` }));
            }
        }

        // ----- Connection (Web Serial) ------------------------------------------------------

        async addDevice() {
            if (!OF.WebSerialTransport.isSupported()) {
                await OF.UI.alert(OF.UI.t('Connection failed'), OF.UI.escape(OF.UI.t('This browser does not support Web Serial: use Chrome, Edge or Opera on a computer.')), 'error');
                return;
            }
            let port;
            try {
                port = await OF.WebSerialTransport.requestPort();
            } catch (error) {
                return;
            }
            if (!port) return;
            await this.connectPort(port);
        }

        async connectPort(port) {
            if (this.connection.isDocked) await this.disconnect();
            this.activePort = port;
            const ok = await this.connection.connectSerial(port);
            if (!ok) this.activePort = null;
        }

        async disconnect() {
            this.closeWindows(false);
            await this.connection.disconnect();
            this.activePort = null;
        }

        // ----- Connection ----------------------------------------------------------------------------

        onConnectionState(state, detail) {
            const t = OF.UI.t;
            this.logNote(`state: ${state} ${JSON.stringify(detail || {})}`);
            switch (state) {
            case 'connecting':
                this.status.show(t('Connecting...'));
                this.lastConnectionError = null;
                break;
            case 'lost':
            case 'idle': {
                const wasLoaded = this.state.loaded;
                const accidental = state === 'lost' && wasLoaded && !this.expectClose;
                // Kept to be offered back when the same gun docks again.
                if (accidental && (this.state.isDirty() || this.state.forceDirty))
                    this.lostEdits = Object.assign(this.state.snapshot(), { port: this.activePort });
                else if (wasLoaded)
                    this.lostEdits = null;
                if (this.expectClose) {
                    this.expectClose = false;
                } else if (detail.stopped) {
                    this.status.show(t('The lightgun was taken over by another page. Close the other page, then press Reconnect.'));
                } else if (accidental) {
                    this.status.show(this.isDevice ? t('Connection lost: reconnecting...') : t('Current board has been disconnected.'));
                }
                // After the message: a calibration cancelled by the loss reports last, like the Qt App.
                this.onDisconnected();
                break;
            }
            case 'error':
                this.lastConnectionError = detail;
                this.expectClose = false;
                this.onDisconnected();
                this.onConnectError(detail);
                break;
            default:
                break;
            }
            this.refresh();
        }

        onProgress(progress) {
            if ('range' in progress) {
                this.status.progressRange(progress.range);
            } else {
                this.status.progress(progress.value);
                if (progress.text) this.status.show(OF.UI.t(progress.text), 5000);
            }
        }

        onDocked(board, config) {
            this.closeWindows(false);
            OF.UI.closeDialogs('session');
            this.session++;
            this.expectClose = false;
            this.irTestActive = false;
            this.irTestStarting = false;
            this.state.load(board, config);
            if (this.activePort) this.portArch.set(this.activePort, board.arch);
            this.titleName = config.tinyUSB.name;
            for (const id of TAB_ORDER) {
                const tab = this.tabs[id];
                if (tab.reload) tab.reload();
                if (tab.onLoad) tab.onLoad();
            }
            this.updateHeader();
            this.selectTab('pins');
            this.status.progressRange(0);
            this.refresh();
            if (board.cameraError) this.showCameraError('warning', false);
            if (this.retryNoticePending) {
                this.retryNoticePending = false;
                if (this.commitNeedsRetry) this.showSaveNotConfirmed();
            }
            this.offerLostEdits();
            if (OF.Version) OF.Version.afterDock(this, board);
            // Shown again here: the messages of the docking would have covered the one
            // that explains why this page opened, which is the only one that needs saying.
            if (this.versionNotice) {
                const notice = this.versionNotice;
                this.versionNotice = '';
                this.status.show(notice, 12000);
            }
        }


        /** The gun docked again after a lost session with unsaved edits: offer them back. */
        async offerLostEdits() {
            const snapshot = this.lostEdits;
            this.lostEdits = null;
            if (!snapshot || (!this.isDevice && snapshot.port !== this.activePort)) return;
            if (!this.state.snapshotDiffers(snapshot)) return;
            const t = OF.UI.t;
            const session = this.session;
            const yes = await OF.UI.confirm(t('Unsaved Changes'), t('The connection was lost before your changes were saved.'),
                t('Restore the changes made before the connection was lost?\n\nCalibrations stay in the board only until it restarts: save them to keep them.'),
                { icon: 'warning', scope: 'session' });
            if (!yes || session !== this.session || !this.state.loaded) return;
            if (!this.state.restoreSnapshot(snapshot)) return;
            for (const id of TAB_ORDER) {
                const tab = this.tabs[id];
                if (tab.reload) tab.reload();
            }
            this.status.show(t('Changes restored: press Save and Send Settings to keep them.'), 5000);
            this.refresh();
        }

        onDisconnected() {
            this.closeWindows(false); // the alignment assistant does not need the board
            if (this.state.loaded) {
                OF.UI.closeDialogs('session');
                this.session++;
            }
            this.irTestActive = false;
            this.irTestStarting = false;
            this.retryNoticePending = false;
            this.busy = false;
            this.state.reset();
            this.status.progressRange(0);
            if (!this.connection.isDocked && !this.isDevice && this.connection.state !== 'connecting')
                this.activePort = null;
        }

        /** What went wrong, in the words of the App protocol (js/core/protocol.js results). */
        connectionErrorText(detail) {
            const t = OF.UI.t;
            switch (detail.error) {
            case 'dock_timeout':
                return t('The lightgun did not answer the connection request: it may be in use by an App on the USB cable or by another page.');
            case 'bad_board_info':
                return t('The lightgun answered with data this App does not understand: check that its firmware and this App belong to the same version.');
            case 'not_open':
            case 'open_failed':
            case 'closed':
                return t('The link to the lightgun closed before the settings were read.');
            default:
                return t('The settings could not be read (%1): the connection dropped during the transfer.', String(detail.error || '?'));
            }
        }

        onConnectError(detail) {
            const t = OF.UI.t;
            const esc = OF.UI.escape;
            if (this.isDevice) {
                // The lightgun page keeps trying: another App (USB) may hold the session.
                this.status.show(t('Waiting for the lightgun... another App may be using it.'));
                this.logNote('connect error: ' + JSON.stringify(detail));
                return;
            }
            this.activePort = null;
            switch (detail.error) {
            case 'port_busy':
            case 'open_failed':
                OF.UI.alert(t('Serial port is already in use!'), esc(t("This usually indicates that the port is being used by something else, e.g. Arduino IDE's serial monitor, or another command line app (stty, screen).\n\nPlease close the offending application and try selecting this port again.")), 'warning');
                break;
            case 'serial_unsupported':
            case 'port_request_failed':
                OF.UI.alert(t('Connection failed'), esc(t('This browser does not support Web Serial: use Chrome, Edge or Opera on a computer.')), 'error');
                break;
            case 'dock_timeout':
            case 'bad_board_info':
                break; // handled by onDockFailure while the port was open
            default:
                this.status.show(t('Connection failed'), 5000);
                break;
            }
        }

        /** Qt AppSerial::GetSettings failure paths: stale dock warning and RequestToReboot. */
        async onDockFailure(result, protocol, kind) {
            if (kind !== 'serial' || !protocol.isOpen) return; // unplugged: nothing to ask
            // The rest of the answer could not be read, but the version was: it is the
            // first field, precisely so that this case can still be recognised. If the
            // site has the App published for that firmware, open it instead of telling
            // the user that the board is broken.
            // A version that does not match explains everything: no point in going on to
            // offer a reboot of a board that is not broken at all.
            if (result.error === 'bad_board_info' && result.board &&
                OF.Version && await OF.Version.afterDock(this, result.board))
                return;
            const t = OF.UI.t;
            if (result.error === 'dock_timeout') {
                await OF.UI.alert(t("Data hasn't arrived! (Stale state?)"), OF.UI.escape(t("Device was detected, but initial settings request wasn't received in time!\nThis can happen if the app was unexpectedly closed and the gun is in a stale docked state.\n\nTry selecting the device again.")), 'warning');
            }
            if ((result.error === 'dock_timeout' || result.error === 'bad_board_info') && protocol.isOpen) {
                const arch = result.board ? result.board.arch : (this.portArch.get(this.activePort) || '');
                const isRP = arch === this.S.boardArchs[this.S.boardArchs_e.boardRP];
                const title = isRP ? t('Reset Board to Bootloader?') : t('Reboot Microcontroller?');
                const text = isRP ?
                    t("<p>The board you selected did not respond to the app properly.</p><p>This can usually be resolved by rebooting the microcontroller to its bootloader, and then updating the board to the latest firmware, which can be found at:</p><p><a href='https://github.com/TeamOpenFIRE/OpenFIRE-Firmware/releases/latest'><span style=' text-decoration: underline; color:#8ab4f8;'>https://github.com/TeamOpenFIRE/OpenFIRE-Firmware/releases/latest</span></a></p><p>Would you like to reboot this board to apply an update?</p>") :
                    t("<p>The board you selected did not respond to the app properly.</p><p>This can usually be resolved by rebooting the microcontroller, and then updating the board to the latest firmware, which can be found at:</p><p><a href='https://github.com/TeamOpenFIRE/OpenFIRE-Firmware/releases/latest'><span style=' text-decoration: underline; color:#8ab4f8;'>https://github.com/TeamOpenFIRE/OpenFIRE-Firmware/releases/latest</span></a></p><p>Would you like to reboot this board to apply an update?</p>");
                if (await OF.UI.confirm(title, null, null, { html: text, icon: 'error' }) && protocol.isOpen)
                    await protocol.rebootToBootloader(arch);
            }
        }

        // ----- Board events (Qt serialPort_readyRead) ----------------------------------------------------

        onEvent(command, payload) {
            const C = this.C;
            const t = OF.UI.t;
            this.logDebug(command, payload);
            if (this.busy && command !== C.sError) return;
            if (!this.state.loaded && command !== C.sError) return;

            if (this.tabs.tests && this.tabs.tests.onEvent(command, payload)) return;

            switch (command) {
            case C.sCurrentProf:
                if (payload.length === 1) {
                    const selection = payload[0];
                    if (selection !== this.state.cur.selectedProfile && selection < this.state.profileCount)
                        this.state.setSelectedProfile(selection);
                    this.refresh();
                }
                break;

            case C.sError:
                this.onError(payload);
                break;

            case C.sCaliStageUpd:
                if (payload.length === 1 && this.window && this.window.mode === OF.FullscreenWindow.MODE_CALIBRATE)
                    this.window.setStage(payload[0]);
                break;

            case C.sCaliInfoUpd:
                if (payload.length === 5 && this.window && this.window.mode === OF.FullscreenWindow.MODE_CALIBRATE)
                    this.window.setInfo(payload);
                break;

            case C.sTestCoords:
                if (this.window) this.window.drawTest(payload);
                break;

            case C.sClearFlash:
                this.showClearFlashDone();
                break;

            default:
                break;
            }
            void t;
        }

        onError(payload) {
            const C = this.C;
            const t = OF.UI.t;
            const retry = OF.ProtocolConstants.APP_SERIAL_ERR_COMMIT_RETRY;
            if (payload.length && payload[0] === retry) {
                // A queued error must not undo a later successful retry; a link that is gone offers
                // the edits back when the board docks again.
                if (!this.commitNeedsRetry || !this.protocol.isOpen) return;
                if (!this.state.loaded) {
                    this.retryNoticePending = true; // the board reported a pending save while docking
                    return;
                }
                this.showSaveNotConfirmed();
                return;
            }
            if (!payload.length) {
                this.closeWindows(true);
                this.expectClose = true;
                this.connection.notifyClosed('operation_failed');
                this.status.show(t('Operation not confirmed: restart the microcontroller and reconnect.'));
                this.showError(t('Operation not confirmed'), OF.UI.escape(t('The operation failed or its result could not be confirmed. Restart the microcontroller and reconnect before continuing. If saving had already started, verify the settings and save them again after resolving the error.')), 'error');
                return;
            }
            switch (payload[0]) {
            case C.sErrCam:
                this.closeWindows(true);
                this.showCameraError('error', true);
                break;
            case C.sErrPeriphGeneric:
                this.showError(t('Peripheral Device Error!'), t("<p>Data received from the board indicates that an I2C peripheral device failed to initialize.<br>" +
                    "This can happen if, for example, the peripheral's wires are crossed<br>" +
                    '(data wire to clock pin, clock wire to data pin),<br>' +
                    'or the pins for the peripheral are set to a different component,<br>' +
                    'such as a button or Force Feedback output.</p>' +
                    '<p>Confirm that the wires for the peripheral are connected to the correct <i>Peripheral I2C</i> pins<br>' +
                    'in the <i>Boards Layout</i> tab.</p>'), 'error');
                break;
            default:
                break;
            }
        }

        showSaveNotConfirmed() {
            const t = OF.UI.t;
            this.refresh();
            this.status.show(t('Save not confirmed. Keep the board powered and retry Save.'));
            this.showError(t('Save not confirmed'), OF.UI.escape(t('Saving failed or its result could not be confirmed. Your edits remain in this App; completed calibration remains in the powered board.\n\n' +
                'Check the connection or the reported storage error, then press Save and Send Settings again. No restart is required for a recoverable save error. Hardware tests stay disabled until a save is confirmed.\n\n' +
                'Disconnecting/reloading can replace unsent App edits with the board\'s partly updated settings. Restarting loses unsaved board RAM.')), 'error', 'session');
        }

        /** Qt AppSerial::ShowError: one board error box at a time, repeated reports are ignored. */
        showError(title, html, iconName, scope) {
            if (this.errorShown) return;
            this.errorShown = true;
            OF.UI.alert(title, html, iconName, { scope }).finally(() => { this.errorShown = false; });
        }

        showCameraError(iconName, testsUnavailable) {
            const t = OF.UI.t;
            const text = testsUnavailable ?
                t('<p>Data received from the board indicates that the camera is in a bad state.<br>' +
                    'This can happen if, for example, the camera wires are crossed<br>' +
                    '(data wire to clock pin, clock wire to data pin),<br>' +
                    'or the camera pins are wired to a different component,<br>' +
                    'such as a button or Force Feedback output.</p>' +
                    '<p>You are able to change the camera pins in the <i>Boards Layout</i> tab<br>' +
                    'if they should be mapped different GPIO;<br>' +
                    'Otherwise, the camera wires must be resoldered to resolve this error.</p>' +
                    '<p>IR Testing and Calibration will not be available while in this state.</p>') :
                t('<p>Data received from the board indicates that the camera is in a bad state.<br>' +
                    'This can happen if, for example, the camera wires are crossed<br>' +
                    '(data wire to clock pin, clock wire to data pin),<br>' +
                    'or the camera pins are wired to a different component,<br>' +
                    'such as a button or Force Feedback output.</p>' +
                    '<p>You are able to change the camera pins in the <i>Boards Layout</i> tab<br>' +
                    'if they should be mapped different GPIO;<br>' +
                    'Otherwise, the camera wires must be resoldered to resolve this error.</p>');
            this.showError(t('Device Error: Camera not available!'), text, iconName);
        }

        // ----- Debug window (Qt AppDebugWindow, non-Release builds) -------------------------------------

        /** Available from the unbundled webapp folder or with ?debug in the address. */
        get debugEnabled() {
            if (!OF.BUILD) return true;
            try { return new URLSearchParams(root.location.search).has('debug'); } catch (e) { return false; }
        }

        openDebugWindow() {
            const { el, t, icon } = OF.UI;
            if (this.debugWindow) {
                this.debugWindow.root.hidden = false;
                return;
            }
            const text = el('textarea', { class: 'debug-text mono', readOnly: true, attrs: { 'aria-label': 'Text' } });
            const hex = el('textarea', { class: 'debug-text mono', readOnly: true, attrs: { 'aria-label': 'Hex' } });
            const panel = el('section', { class: 'debug-window', attrs: { role: 'dialog', 'aria-label': t('Serial Debug') } },
                el('div', { class: 'debug-head' },
                    el('strong', { text: t('Serial Debug') }),
                    el('span', { class: 'spacer' }),
                    el('button', { text: t('Clear'), on: { click: () => { text.value = ''; hex.value = ''; } } }),
                    el('button', { class: 'icon-button', title: t('Close'), on: { click: () => { panel.hidden = true; } } }, icon('close'))),
                text, hex);
            doc.body.append(panel);
            this.debugWindow = { root: panel, text, hex };
        }

        /** Line written in the debug window (unbundled folder or ?debug), without a board event. */
        logNote(text) {
            const win = this.debugWindow;
            if (!win) return;
            win.text.value = (win.text.value + `[${new Date().toLocaleTimeString()}] ${text}\n`).slice(-40000);
            win.text.scrollTop = win.text.scrollHeight;
        }

        logDebug(command, payload) {
            const win = this.debugWindow;
            if (!win) return;
            const bytes = Array.from(payload || []);
            const append = (area, value) => {
                area.value = (area.value + value).slice(-40000);
                area.scrollTop = area.scrollHeight;
            };
            append(win.text, String.fromCharCode(...bytes) + '\n');
            append(win.hex, ` [${command.toString(16).toUpperCase().padStart(2, '0')}]` +
                bytes.map((b) => ' ' + b.toString(16).toUpperCase().padStart(2, '0')).join(''));
        }

        // ----- Commands ----------------------------------------------------------------------------------

        async sendCommand(command, payload) {
            if (!this.connection.isDocked) return false;
            return this.protocol.sendCommand(command, payload ? Uint8Array.from(payload) : null);
        }

        selectProfile(profile) {
            this.sendCommand(this.C.sCaliProfile, [this.C.sCaliProfile, profile]);
        }

        calibrate(profile) {
            const C = this.C;
            if (!this.connected || this.window && this.window.mode !== OF.FullscreenWindow.MODE_ALIGNMENT) return;
            const settings = this.state.cur.profiles[profile];
            if (this.window) this.window.shutdown();
            this.caliProfile = profile;
            const win = new OF.FullscreenWindow(OF.FullscreenWindow.MODE_CALIBRATE, {
                onExitRequest: () => this.sendCommand(C.serialTerminator).then((ok) => { if (!ok) this.failOperation(); }),
                onExit: (mode, values) => this.onWindowExit(win, mode, values),
            });
            this.window = win;
            win.open();
            this.sendCommand(C.sCaliProfile, [C.sCaliStart, profile, (settings.irSensitivity + (settings.layoutType << 4)) & 0xFF])
                .then((ok) => { if (!ok) this.failOperation(); });
        }

        failOperation() {
            if (this.connection.isDocked) this.protocol.failOperation();
        }

        openAlignment() {
            if (this.window && this.window.mode !== OF.FullscreenWindow.MODE_ALIGNMENT) return;
            if (this.window) this.window.shutdown();
            const win = new OF.FullscreenWindow(OF.FullscreenWindow.MODE_ALIGNMENT, { onExit: (mode) => this.onWindowExit(win, mode) });
            this.window = win;
            win.open();
        }

        async openIRTest() {
            const t = OF.UI.t;
            if (!this.connected || this.irTestStarting || this.irTestActive) return; // double click
            if (this.window && this.window.mode !== OF.FullscreenWindow.MODE_ALIGNMENT) return;
            const session = this.session;
            this.irTestStarting = true;
            try {
                if (this.state.layoutChangedUnsaved()) {
                    const proceed = await OF.UI.confirm(t('Warning: Unsaved Changes'),
                        t("Your current calibration profile has an unsaved IR Layout type change.\nTest Mode relies on the profile's settings since the last save, and may not work as expected.\nIt is recommended that you save your changes before continuing.\n\nContinue to Test Mode?"),
                        null, { icon: 'info', scope: 'session' });
                    if (!proceed || session !== this.session) return;
                }
                if (!await this.sendCommand(this.C.sIRTest, [1]) || session !== this.session) return;
            } finally {
                if (session === this.session) this.irTestStarting = false;
            }
            if (this.window) this.window.shutdown();
            this.irTestActive = true;
            const win = new OF.FullscreenWindow(OF.FullscreenWindow.MODE_IRTEST, { onExit: (mode) => this.onWindowExit(win, mode) });
            this.window = win;
            win.open();
            this.refresh();
        }

        /** Qt CaliWindowExiting. */
        async onWindowExit(win, mode, values) {
            const t = OF.UI.t;
            if (this.window === win) this.window = null;
            if (mode === OF.FullscreenWindow.MODE_CALIBRATE) {
                const profile = this.caliProfile;
                if (!this.state.loaded || profile < 0) return;
                const empty = { topOffset: -1, bottomOffset: -1, leftOffset: -1, rightOffset: -1, TLled: -1, TRled: -1 };
                const result = this.state.applyCalibration(profile, values || empty);
                const n = profile + 1;
                if (result === 'ok') this.status.show(t('Calibration for Profile ') + n + t(' successful'), 5000);
                else if (result === 'malformed') this.status.show(t('Calibration for Profile ') + n + t(' returned with malformed values.'), 10000);
                else this.status.show(t('Cancelled Calibration for Profile ') + n, 10000);
                this.refresh();
            } else if (mode === OF.FullscreenWindow.MODE_IRTEST) {
                if (!this.connection.isDocked) {
                    this.irTestActive = false;
                    this.refresh();
                } else if (await this.sendCommand(this.C.sIRTest, [0])) {
                    this.irTestActive = false;
                    this.refresh();
                } else {
                    // Test mode could not be left: the board must be restarted (fatal error dialog).
                    this.failOperation();
                }
            }
        }

        /** Closes the fullscreen windows (the alignment assistant stays unless everything closes). */
        closeWindows(all) {
            // Like Qt Shutdown(): the window reports its exit (cancelled calibration, IR test mode off).
            if (this.window && (all || this.window.mode !== OF.FullscreenWindow.MODE_ALIGNMENT))
                this.window.shutdown();
            if (all) this.irTestActive = false;
        }

        async rebootToBootloader() {
            const t = OF.UI.t;
            if (!this.connected) return;
            const rp = this.state.isRP;
            this.expectClose = true;
            const sent = await this.protocol.rebootToBootloader(this.state.board.arch);
            this.connection.notifyClosed('bootloader');
            // A restart that never left the page used to be reported as done.
            if (sent) this.status.show(rp ? t('Board reset to bootloader.') : t('Board restarted.'), 5000);
            else this.status.show(t('The restart command could not be sent: reconnect and try again.'));
        }

        async clearSaveMemory() {
            const t = OF.UI.t;
            if (!this.connected) return;
            const session = this.session;
            const yes = await OF.UI.confirm(t('Delete Confirmation'), t('Really delete saved data?'),
                t('This operation will delete all saved data, including:\n\n - Calibration Profiles\n - Toggles\n - Settings\n - Custom Identifiers\n\nAre you sure about this?'),
                { icon: 'warning', defaultNo: true, danger: true, scope: 'session' });
            if (session !== this.session || !this.connected) return;
            if (!yes) {
                this.status.show(t('Clear operation canceled.'), 3000);
                return;
            }
            this.status.show(t('Board reset to initial settings.'));
            this.expectClose = true;
            this.clearFlashShown = false;
            const sent = await this.protocol.clearSaveMemory();
            this.connection.notifyClosed('clear_flash');
            if (sent) this.showClearFlashDone();
        }

        showClearFlashDone() {
            if (this.clearFlashShown) return;
            this.clearFlashShown = true;
            const t = OF.UI.t;
            OF.UI.alert(t('Successfully reset board settings'), OF.UI.escape(t('Please unplug the board and reinsert it into the PC.')), 'info');
        }

        // ----- Save (Qt on_confirmButton_clicked) ------------------------------------------------------

        async save() {
            const t = OF.UI.t;
            if (!this.connected || this.busy || this.irTestActive) return;
            const session = this.session;
            const yes = await OF.UI.confirm(t('Commit Confirmation'), t('Are these settings okay?'),
                t('These settings will be committed to your lightgun. Is that okay?'), { icon: 'info', scope: 'session' });
            if (session !== this.session || !this.connected || this.busy) return;
            if (!yes) {
                this.status.show(t('Save operation canceled.'), 3000);
                return;
            }
            const cameraChanged = this.state.cameraChanged;
            // The edits being sent: later changes (none while busy) are not marked as saved.
            const sent = this.state.clone(this.state.cur);
            this.busy = true;
            this.refresh();
            let result;
            try {
                result = await this.protocol.commitSettings(sent, this.state.orig);
            } catch (error) {
                console.error(error);
                result = { ok: false };
            }
            if (session !== this.session) return; // the session ended during the save (onDisconnected reset the UI)
            this.busy = false;
            this.status.progressRange(0);
            if (result.ok && this.state.loaded) {
                this.status.show(t('Sent settings successfully!'), 5000);
                this.state.commitDone();
                this.titleName = this.state.cur.tinyUSB.name;
                this.updateHeader();
                this.tabs.tests.resetReadings();
                if (cameraChanged) {
                    OF.UI.dialog({
                        title: t('Camera Changed'), text: t('Camera Model Changed Successfully'), icon: 'info',
                        info: t('The lightgun has automatically swapped the active sensors.\n\nIf you experience any unexpected issues or the new camera fails to respond, we recommend physically restarting the microcontroller.'),
                        buttons: [{ label: t('OK'), value: true, primary: true }],
                    });
                }
            }
            this.refresh();
        }
    }

    OF.APP_NAME = APP_NAME;
    OF.App = App;

    if (doc && !root.OF_NO_AUTOSTART) {
        const boot = () => {
            OF.app = new App();
            OF.app.start();
        };
        if (doc.readyState === 'loading') doc.addEventListener('DOMContentLoaded', boot);
        else boot();
    }
})(typeof globalThis !== 'undefined' ? globalThis : this);
;
